if (!row) {
  console.log(`${label}\\tFAIL\\tmissing-row\\t${runPath}`);
  process.exit(0);
}
const [, id, , passA, passB, passC] = row.split('\\t');
const patterns = [passA, passB, passC].filter(Boolean);
const text = fs.readFileSync(runPath, 'utf8');
